CREATE TABLE "user" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar(50) NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "birthday" date,
  "created_at" timestamp DEFAULT 'now()',
  "update_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "categories" (
  "id" SERIAL PRIMARY KEY,
  "name" varchar(50) NOT NULL,
  "description" text,
  "icon_key" varchar(30),
  "type" varchar(10) NOT NULL
);

CREATE TABLE "transactions" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "ammount" numeric(19,2) NOT NULL,
  "transaction_date" timestamp NOT NULL,
  "category_id" int,
  "user_id" int,
  "is_automated" boolean DEFAULT false,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "financial_goals" (
  "id" serial PRIMARY KEY,
  "tittle" varchar(100) NOT NULL,
  "target_amount" numeric(19,2) NOT NULL,
  "current_amount" numeric(19,2) DEFAULT 0,
  "deadline" date,
  "priority" int DEFAULT 1,
  "user_id" int
);

-- ALTER TABLE "categories" ADD FOREIGN KEY ("id") REFERENCES "transactions" ("category_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "transactions" ADD FOREIGN KEY ("category_id") REFERENCES "categories" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "transactions" ADD FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "financial_goals" ADD FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE;
